/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trig_ast_transaction_update` BEFORE UPDATE ON `ast_transaction` FOR EACH ROW BEGIN
    INSERT INTO `ast_transaction_audit` (
        `AuditAction`, `TID`, `Date`, `AccountNo`, `Amount`, 
        `AYID`, `ATMID`, `TransactionType`, `TransactionMethod`, `ChallanNo`, 
        `ACode`, `ASubCode`, `InterestType`, `IsManagerApproved`, `ManagerApprovedDate`, 
        `IsDirectorApproved`, `DirectorApprovedDate`, `PROrIntOrPen`, `Remarks`, `UserId`, 
        `Narration`
    ) VALUES (
        'UPDATE', OLD.`TID`, OLD.`Date`, OLD.`AccountNo`, OLD.`Amount`, 
        OLD.`AYID`, OLD.`ATMID`, OLD.`TransactionType`, OLD.`TransactionMethod`, OLD.`ChallanNo`, 
        OLD.`ACode`, OLD.`ASubCode`, OLD.`InterestType`, OLD.`IsManagerApproved`, OLD.`ManagerApprovedDate`, 
        OLD.`IsDirectorApproved`, OLD.`DirectorApprovedDate`, OLD.`PROrIntOrPen`, OLD.`Remarks`, OLD.`UserId`, 
        OLD.`Narration`
    );
END */;;
